// Raw STREAM_MAGIC capture generated by the original native event serializer.
// Existing checked-in .pxd2 fixtures contain FILE_MAGIC indexed databases.
#include "PvdSimpleAllocator.h"
#include "PxFoundation.h"
#include "PxFoundationVersion.h"
#include "PxErrorCallback.h"
#include "PxPvdCommStreamEventSink.h"
#include "PxPvdCommStreamEvents.h"
#include "PxPvdInternalByteStreams.h"
#include <fstream>
#include <string>

using namespace physx;
using namespace physx::pvdsdk;
template<class T> void write(std::ofstream& out,const T& value) {
    out.write(reinterpret_cast<const char*>(&value),sizeof(value));
}
template<class T> void event(std::ofstream& out,const T& value) {
    MemPvdOutputStream stream("ingestion-fixture");
    PvdCommStreamEventSink::writeStreamEvent(value,getCommStreamEventType<T>(),stream);
    const auto bytes=stream.toRef();
    write(out,PxU32(bytes.size()));write(out,PxU32(1));
    write(out,PxU64(1));write(out,PxU64(0));
    out.write(reinterpret_cast<const char*>(bytes.begin()),bytes.size());
}
int main(int argc,char** argv) {
    if(argc!=3 && argc!=4)return 2;
    struct Error:PxErrorCallback {void reportError(PxErrorCode::Enum,const char*,const char*,int) override {}} error;
    pvdapp::CheckingAllocator allocator;
    auto* foundation=PxCreateFoundation(PX_FOUNDATION_VERSION,allocator,error);
    if(!foundation)return 3;
    {
        std::ofstream out(argv[1],std::ios::binary);
        if(!out){foundation->release();return 4;}
        write(out,StreamInitialization::getStreamId());
        write(out,StreamInitialization::getStreamVersion());
        write(out,PxU64(1));write(out,PxU64(1));write(out,PxU32(sizeof(void*)==8));
        event(out,StringHandleEvent("physx3",1));
        event(out,StringHandleEvent("PxScene",2));
        event(out,StringHandleEvent("frame",3));
        const StreamNamespacedName scene(StringHandle(1),StringHandle(2));
        event(out,CreateClass(scene));event(out,CreateInstance(scene,100));
        const auto count=std::stoul(argv[2]);
        for(unsigned long frame=1;frame<=count;++frame) {
            event(out,BeginSection(100,StringHandle(3),frame*100));
            event(out,EndSection(100,StringHandle(3),frame*100+50));
        }
        if(argc==4) {
            event(out,CreateInstance(scene,200));
            const auto otherCount=std::stoul(argv[3]);
            for(unsigned long frame=1;frame<=otherCount;++frame) {
                event(out,BeginSection(200,StringHandle(3),(count+frame)*100));
                event(out,EndSection(200,StringHandle(3),(count+frame)*100+50));
            }
        }
        event(out,StreamEndEvent());
        out.flush();
        if(!out){foundation->release();return 5;}
    }
    foundation->release();return 0;
}
